tool-monitor-description

Parameters:
```json
{
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "description": "Shell command to run in the background. Each time it produces new output, you will be woken up (when idle) or notified at the next natural turn boundary (when busy) with the incremental content — you do NOT need to poll TaskOutput/BashOutput in a loop. Mutually exclusive with `ws`."
    },
    "ws": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "WebSocket endpoint to connect to. Must be a ws:// or wss:// URL with no embedded credentials or whitespace, using ASCII characters only."
        },
        "protocols": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Optional WebSocket subprotocol names to offer during the handshake. Each entry must be a valid subprotocol token, and the list cannot contain duplicates."
        }
      },
      "required": [
        "url"
      ],
      "additionalProperties": false,
      "description": "WebSocket event source: connect to a server that already pushes events, and treat each incoming message as one event. Mutually exclusive with `command`."
    },
    "timeout_ms": {
      "type": "number",
      "description": "How long to keep monitoring before automatically stopping, in milliseconds. Defaults to 600000ms. Ignored when persistent=true."
    },
    "persistent": {
      "type": "boolean",
      "description": "Set to true to keep monitoring indefinitely past timeout_ms. Still stoppable early via TaskStop."
    }
  },
  "additionalProperties": false,
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

